using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed partial class StateQ {public List<ResourceFieldQ> Fields{get;set;}=[];}
public sealed class ResourceFieldQ {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string System{get;set;}="";public string Grid{get;set;}="";public string Moon{get;set;}="";public SpacePosition Anchor{get;set;}public string Kind{get;set;}="Phase";public string State{get;set;}="Unbreached";public DateTime Started{get;set;}public DateTime Due{get;set;}public DateTime Last{get;set;}public string Facility{get;set;}="";public bool Stabilizer{get;set;}public double Energy{get;set;}public decimal Remaining{get;set;}=10000;public decimal Mineable{get;set;}public decimal Harvested{get;set;}public Dictionary<string,decimal> Output{get;set;}=[];public List<string> Connected{get;set;}=[];}
public sealed partial class DemoWorld {
 public string DiscoverMiningQ(){if(Docked||InWarp||Commander.Capsule||Current.Security>.4||SystemsQ.Fields.Any(f=>f.System==SystemId&&f.Kind=="Phase"))return "Undock in low/null security; a finite field is created only once per system.";var f=new ResourceFieldQ{System=SystemId,Grid=SolarGridKey,Anchor=SystemPosition+new SpacePosition(5000,0,0),Started=Now,Due=Now.AddHours(1),Last=Now};SystemsQ.Fields.Add(f);Bookmarks.Add(new("q-field:"+f.Id,SystemId,"Phased mining field",f.Anchor));BindMiningQ();return "";}
 public string SurveyMoonQ(string moon){var m=SolarCatalog.ById.GetValueOrDefault(moon);if(m==null||m.Kind!=CelestialKind.Moon||m.System!=SystemId||Docked||Current.Security>.4||SystemsQ.Fields.Any(f=>f.Moon==moon))return "Survey a local low/null security moon in space; a deposit is finite and unique.";if(!Player.Utilities.Any(u=>u.Online&&!u.Burnt&&u.Definition?.Kind is "Survey" or "SurveyProbe"))return "Fit an online survey scanner or survey probe launcher.";var f=new ResourceFieldQ{System=SystemId,Moon=moon,Grid=SolarCatalog.GridKey(SystemId,m.WarpPosition),Anchor=m.WarpPosition,Kind="Moon",State="Surveyed",Started=Now,Last=Now,Remaining=100000};SystemsQ.Fields.Add(f);Bookmarks.Add(new("q-field:"+f.Id,SystemId,"Surveyed moon extraction",f.Anchor));return "";}
 public string ScheduleMoonQ(string id,string facility,bool automated){var f=SystemsQ.Fields.FirstOrDefault(f=>f.Id==id&&f.Kind=="Moon"&&f.State=="Surveyed");var s=Organisations.Structures.FirstOrDefault(s=>s.Id==facility&&s.Kind=="Refinery"&&s.PhysicalQ&&s.State=="Online"&&s.System==SystemId&&s.Corp==Organisations.PlayerCorp);if(f==null||s==null||!HasRoleG("Station Manager")||f.System!=SystemId||s.Fuel<10)return "Local surveyed moon, owned physical online refinery and ten real fuel units required.";s.Fuel-=10;f.Facility=s.Id;f.State=automated?"Automated":"Extracting";f.Due=Now.AddHours(24);f.Last=Now;return "";}
 public string FractureMoonQ(string id){var f=SystemsQ.Fields.FirstOrDefault(f=>f.Id==id&&f.State=="Chunk ready");if(f==null||Docked||f.System!=SystemId||(SystemPosition-f.Anchor).Length>2500)return "Approach a ready physical moon chunk within 2,500 m.";f.Mineable=Math.Min(1000,f.Remaining);f.Remaining-=f.Mineable;f.State="Fractured";BindMiningQ();return "";}
 public string StabilizeMiningQ(string id){var f=SystemsQ.Fields.FirstOrDefault(f=>f.Id==id&&f.Kind=="Phase");if(f==null||f.State=="Collapsed"||Docked||f.System!=SystemId||(SystemPosition-f.Anchor).Length>2500||f.Stabilizer||ItemCount("q_resource_anchor",false)<1)return "Approach a live unanchored field with an owned stabilizer kit.";ChangeStack("q_resource_anchor",false,-1);f.Stabilizer=true;return "";}
 public string ConnectMiningQ(string id,string actor="player"){var f=SystemsQ.Fields.FirstOrDefault(f=>f.Id==id&&f.Kind=="Phase"&&f.Stabilizer&&f.State!="Collapsed");var p=PopulationPilot(actor);var ship=actor=="player"?Player:p?.Fit;var pos=actor=="player"?SystemPosition:p==null?default:SolarOrigin+SpacePosition.From(p.Position);if(f==null||Docked||f.System!=SystemId||ship==null||(pos-f.Anchor).Length>15000||actor!="player"&&(p is not{Contracted:true,Suspended:false,Status:"Fleet"}||!Targets.Any(t=>t.Id==actor&&t.Alive))||CombatHulls.Get(ship.CombatHull).Role is not("CapitalIndustrial" or "ExpeditionCommand" or "MiningTender"))return "Owned stabilizer and a nearby eligible industrial command hull required.";if(!f.Connected.Contains(actor))f.Connected.Add(actor);return "";}
 public void BindMiningQ(){if(Docked)return;foreach(var f in SystemsQ.Fields.Where(f=>f.System==SystemId&&f.Grid==SolarGridKey&&f.State is not("Collapsed" or "Depleted"))){if(!Targets.Any(t=>t.Id=="q-field:"+f.Id))Targets.Add(new(){Id="q-field:"+f.Id,Name=f.Kind+" resource controller / "+f.State,Kind=TargetKind.Celestial,Position=(f.Anchor-SolarOrigin).Local,OwnerId="player",Signature=1000});decimal amount=f.Kind=="Phase"?f.Remaining:f.Mineable;if((f.State=="Breached"||f.State=="Fractured")&&amount>0&&!Targets.Any(t=>t.Id=="q-rock:"+f.Id))Targets.Add(new(){Id="q-rock:"+f.Id,Name=f.Kind=="Phase"?"Finite phased prism seam":"Finite fractured moon seam",Kind=TargetKind.Asteroid,Position=(f.Anchor-SolarOrigin).Local+new Vector3(1800,0,0),Resource=f.Kind=="Phase"?"e_prism":"e_moon",Ore=(float)amount,OwnerId="player",Signature=250});var rock=Targets.FirstOrDefault(t=>t.Id=="q-rock:"+f.Id);if(rock!=null)rock.Ore=(float)amount;}}
 public float HarvestMiningQ(SpaceTarget target,float volume){var f=SystemsQ.Fields.FirstOrDefault(f=>"q-rock:"+f.Id==target.Id);if(f==null||f.System!=SystemId||f.State is not("Breached" or "Fractured")||volume<=0)return 0;string item=f.Kind=="Phase"?"e_prism":"e_moon";decimal available=f.Kind=="Phase"?f.Remaining:f.Mineable;decimal efficiency=f.Kind=="Phase"?Math.Clamp((decimal)f.Energy/100,.1m,1):1;decimal q=Math.Min(available,Math.Min((decimal)volume*efficiency/(decimal)ItemVolume(item),(decimal)(CargoRoom(item)/ItemVolume(item))));if(q<=0)return 0;ChangeStack(item,false,q);if(f.Kind=="Phase")f.Remaining-=q;else f.Mineable-=q;f.Harvested+=q;target.Ore=(float)(f.Kind=="Phase"?f.Remaining:f.Mineable);if(target.Ore<=0)f.State=f.Remaining<=0?"Depleted":"Surveyed";return (float)q;}
 public string CollectDrillQ(string id,bool steal=false){var f=SystemsQ.Fields.FirstOrDefault(f=>f.Id==id&&(f.State is "Automated" or "Depleted"));var s=Organisations.Structures.FirstOrDefault(s=>s.Id==f?.Facility);if(f==null||s==null||Docked||f.System!=SystemId||(SystemPosition-f.Anchor).Length>2500||!steal&&s.Corp!=Organisations.PlayerCorp||f.Output.GetValueOrDefault("e_moon")<=0)return "Approach an operating drill with output and ownership or robbery intent.";decimal q=Math.Min(f.Output["e_moon"],(decimal)(CargoRoom("e_moon")/ItemVolume("e_moon")));if(q<=0)return "Cargo full.";if(steal&&!LegalTheftQ(s.Corp))return "Safety blocks theft.";f.Output["e_moon"]-=q;ChangeStack("e_moon",false,q);return "";}
 public string BuyResourceKitQ(bool entosis=false){if(!Docked||Balance<(entosis?1000:1500))return "Dock with the kit's construction credits.";string item=entosis?"q_entosis":"q_resource_anchor";WalletChange(-(entosis?1000:1500),"Physical field equipment");Hangar[item]=Hangar.GetValueOrDefault(item)+1;return "";}
 public void TickMiningQ(double seconds){foreach(var f in SystemsQ.Fields){if(f.Kind=="Phase"){if(Now>=f.Started.AddHours(4)){f.State="Collapsed";f.Connected.Clear();Targets.RemoveAll(t=>t.Id=="q-rock:"+f.Id);continue;}if(f.State=="Unbreached"&&Now>=f.Due)f.State="Breached";if(f.System==SystemId&&!Docked&&!InWarp&&seconds>0){f.Energy=Math.Max(0,f.Energy-seconds*5);foreach(string id in f.Connected.ToArray()){var p=PopulationPilot(id);var actor=id=="player"?null:Targets.FirstOrDefault(t=>t.Id==id&&t.Alive);var ship=id=="player"?Player:p?.Fit;var pos=id=="player"?SystemPosition:actor==null?default:SolarOrigin+SpacePosition.From(actor.Position);if(ship==null||CombatHulls.Get(ship.CombatHull).Role is not("CapitalIndustrial" or "ExpeditionCommand" or "MiningTender")||id!="player"&&(actor==null||p is not{Contracted:true,Suspended:false,Status:"Fleet"})||(pos-f.Anchor).Length>15000){f.Connected.Remove(id);continue;}float cost=(float)(seconds*5);float cap=id=="player"?Player.Cap:actor!.Cap;if(cap<cost)continue;if(id=="player")Player.Cap-=cost;else actor!.Cap-=cost;double power=CombatHulls.Get(ship.CombatHull).Role=="CapitalIndustrial"?100:CombatHulls.Get(ship.CombatHull).Role=="ExpeditionCommand"?50:35;f.Energy=Math.Min(100,f.Energy+seconds*power/10);}}}
  if(f.Kind=="Moon"&&f.State=="Extracting"&&Now>=f.Due)f.State="Chunk ready";if(f.Kind=="Moon"&&f.State=="Automated"){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==f.Facility);long hours=(long)Math.Floor(Math.Max(0,(Now-f.Last).TotalHours));f.Last=f.Last.AddHours(hours);if(s is not{State:"Online"}||hours<=0)continue;decimal cycles=Math.Min(hours,Math.Min(decimal.Floor(s.Fuel),decimal.Ceiling(f.Remaining/50)));decimal raw=Math.Min(f.Remaining,cycles*50);s.Fuel-=cycles;f.Remaining-=raw;f.Harvested+=raw*.4m;f.Output["e_moon"]=f.Output.GetValueOrDefault("e_moon")+raw*.4m;if(f.Remaining<=0)f.State="Depleted";}}
  BindMiningQ();
 }
}
